using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResource
{
    [McpServerResource(
        UriTemplate = "config://app/settings",
        Name = "App Settings",
        MimeType = "application/json"),
     Description("Returns the current application configuration as JSON.")]
    public static string GetAppSettings()
    {
        var config = new
        {
            Environment = "Production",
            MaxRetries = 3,
            TimeoutSeconds = 30,
            Features = new { DarkMode = true, BetaAccess = false }
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Check if a feature flag is enabled.")]
    public static string CheckFeature(
        [Description("Name of the feature flag to check")] string featureName)
    {
        // In a real app, read from a config store or database
        var features = new Dictionary<string, bool>
        {
            ["DarkMode"] = true,
            ["BetaAccess"] = false,
            ["Notifications"] = true
        };

        if (features.TryGetValue(featureName, out var enabled))
            return $"Feature '{featureName}' is {(enabled ? "enabled" : "disabled")}.";

        return $"Feature '{featureName}' not found.";
    }

    [McpServerTool, Description("Get the server's current uptime information.")]
    public static string GetUptime()
    {
        var uptime = DateTime.UtcNow - System.Diagnostics.Process.GetCurrentProcess().StartTime.ToUniversalTime();
        return $"Server uptime: {uptime.Hours}h {uptime.Minutes}m {uptime.Seconds}s";
    }
}

